//! Project-scoped language contracts emitted from the normalized compiler model.

use super::*;
use std::fmt::Write;

pub(super) fn generate(
    artifacts: &mut BTreeMap<String, GeneratedArtifact>,
    registry_id: &str,
    entities: &BTreeMap<String, CompiledEntity>,
    actions: &CompiledActionInventory,
) -> Result<(), Diagnostic> {
    let mut ts = String::from(
        "// Generated by BReg. Edit the project, then regenerate.\nimport type { breg } from '@registrystack/client';\n",
    );
    ts.push_str(TYPESCRIPT_CONTRACT);
    let mut py = String::from(
        "# Generated by BReg. Edit the project, then regenerate.\nfrom __future__ import annotations\nfrom typing import TypedDict, NotRequired, Literal, Protocol, TypeVar, Generic, Any, Callable, overload, cast\nfrom dataclasses import dataclass\n\n",
    );
    py.push_str(PYTHON_CONTRACT);
    for entity in entities.values() {
        let fields = entity
            .stored_fields
            .iter()
            .map(|field| {
                (
                    field.logical.api_name.as_str(),
                    field_value_schema(&field.logical.field_type, !field.required),
                    field.required,
                )
            })
            .collect::<Vec<_>>();
        write_types(&mut ts, &mut py, &entity.api_name, &fields);
        let projection_fields = fields
            .iter()
            .map(|(name, schema, _)| (*name, schema.clone(), false))
            .collect::<Vec<_>>();
        write_types(
            &mut String::new(),
            &mut py,
            &format!("{}Projection", entity.api_name),
            &projection_fields,
        );
    }
    for action in actions.public_actions() {
        let name = type_name(&action.api_name);
        if let Some(context) = crate::compiler::review_context::compile_schema_from_parts(
            registry_id,
            entities,
            action,
        )? {
            let properties = context.schema["properties"]
                .as_object()
                .expect("compiled context schema has properties");
            let fields = properties
                .iter()
                .map(|(name, schema)| (name.as_str(), schema.clone(), true))
                .collect::<Vec<_>>();
            write_types(&mut ts, &mut py, &format!("{name}ReviewContext"), &fields);
            writeln!(ts,"export const {name}ReviewContextContract = {} as const;",serde_json::to_string(&json!({"id":context.id,"revision":context.revision,"digest":context.digest,"path":format!("generated/review-context-schemas/{}.schema.json",action.id)})).expect("context identity serializes")).unwrap();
            writeln!(py,"{name}ReviewContextContract = {}\n",python_literal(&json!({"id":context.id,"revision":context.revision,"digest":context.digest,"path":format!("generated/review-context-schemas/{}.schema.json",action.id)}))).unwrap();
        }
        let fields = action
            .inputs
            .iter()
            .map(|input| {
                (
                    input.api_name.as_str(),
                    field_value_schema(
                        &input.field_type,
                        !input.required && action.handler.is_some(),
                    ),
                    input.required,
                )
            })
            .collect::<Vec<_>>();
        write_types(&mut ts, &mut py, &format!("{name}Input"), &fields);
        let projected = fields
            .iter()
            .map(|(name, schema, _)| (*name, schema.clone(), false))
            .collect::<Vec<_>>();
        write_types(
            &mut String::new(),
            &mut py,
            &format!("{name}InputProjection"),
            &projected,
        );
        let codes = action
            .handler
            .as_ref()
            .map(|function| {
                function
                    .refusals
                    .keys()
                    .map(String::as_str)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let ts_codes = codes
            .iter()
            .map(|code| quote(code))
            .collect::<Vec<_>>()
            .join(" | ");
        let py_codes = codes
            .iter()
            .map(|code| quote(code))
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(
            ts,
            "export type {name}Refusal = EngineReason{};",
            if codes.is_empty() {
                String::new()
            } else {
                format!(" | {ts_codes}")
            }
        )
        .unwrap();
        writeln!(
            py,
            "{name}Refusal = EngineReason{}\n",
            if codes.is_empty() {
                String::new()
            } else {
                format!(" | Literal[{py_codes}]")
            }
        )
        .unwrap();
        if matches!(
            action.execution,
            crate::model::CompiledActionExecution::Proposal { .. }
        ) {
            writeln!(
                ts,
                "export type {name}Result = Proposal<{name}Input, {name}Refusal>;\n"
            )
            .unwrap();
            writeln!(py, "{name}Result = Proposal[{name}InputProjection]\n").unwrap();
        } else {
            writeln!(ts, "export interface {name}Result {{ readonly action: {}; readonly applicationId: string; readonly results: {{", quote(&action.id)).unwrap();
            for effect in action
                .effects
                .iter()
                .filter(|effect| action.result_effects.contains(&effect.id))
            {
                let target = &entities[&effect.target.entity_id];
                writeln!(
                    ts,
                    "  readonly {}?: RecordReference<{}>;",
                    quote(&effect.id),
                    target.api_name
                )
                .unwrap();
            }
            ts.push_str("} }\n");
            let result_fields = action
                .effects
                .iter()
                .filter(|effect| action.result_effects.contains(&effect.id))
                .map(|effect| format!("{}: NotRequired[RecordReference]", quote(&effect.id)))
                .collect::<Vec<_>>()
                .join(", ");
            writeln!(
                py,
                "{name}ResultLinks = TypedDict({}, {{{result_fields}}})",
                quote(&format!("{name}ResultLinks"))
            )
            .unwrap();
            writeln!(py, "{name}Result = TypedDict({}, {{\"action\": Literal[{}], \"applicationId\": str, \"results\": {name}ResultLinks}})\n", quote(&format!("{name}Result")), quote(&action.id)).unwrap();
        }
    }
    ts.push_str("export interface ProjectRecords {\n");
    for entity in entities.values() {
        writeln!(ts, "  {}: {};", quote(&entity.id), entity.api_name).unwrap();
    }
    ts.push_str("}\nexport interface ProjectActions {\n");
    for action in actions.public_actions() {
        let name = type_name(&action.api_name);
        writeln!(
            ts,
            "  {}: {{ input: {name}Input; result: {name}Result }};",
            quote(&action.id)
        )
        .unwrap();
    }
    ts.push_str("}\nexport interface ProjectRelationships {\n");
    for entity in entities.values() {
        writeln!(ts, "  {}: {{", quote(&entity.id)).unwrap();
        for relationship in entity.relationships.values() {
            let target = &entities[&relationship.target_entity_id];
            let value = format!("RecordView<{}>", target.api_name);
            let shape = match relationship.cardinality {
                crate::model::RelationshipCardinality::One => value,
                crate::model::RelationshipCardinality::OptionalOne => format!("{value} | null"),
                crate::model::RelationshipCardinality::Many => format!("Page<{value}>"),
            };
            writeln!(ts, "    {}: {shape};", quote(&relationship.name)).unwrap();
        }
        for path in entity.read_paths.values() {
            if let Some(target) = entities.get(&path.to) {
                writeln!(
                    ts,
                    "    {}: Page<RecordView<{}>>;",
                    quote(&path.id),
                    target.api_name
                )
                .unwrap();
            }
        }
        ts.push_str("  };\n");
    }
    ts.push_str("}\n");
    let definitions = project_definitions(entities, actions);
    writeln!(
        ts,
        "const definitions: ProjectDefinitions = {};",
        serde_json::to_string(&definitions).expect("definitions serialize")
    )
    .unwrap();
    writeln!(
        py,
        "_definitions: dict[str, Any] = {}\n",
        python_literal(&definitions)
    )
    .unwrap();
    ts.push_str(TYPESCRIPT_CLIENT);
    let mut read_overloads = String::new();
    for entity in entities.values() {
        writeln!(read_overloads,"    @overload\n    def read(self, record_type: Literal[{}], identifier: str) -> RecordView[{}Projection]: ...",quote(&entity.id),entity.api_name).unwrap();
    }
    let mut related_overloads = String::new();
    for entity in entities.values() {
        for relationship in entity.relationships.values() {
            let target = &entities[&relationship.target_entity_id];
            let value = format!("RecordView[{}Projection]", target.api_name);
            let shape = match relationship.cardinality {
                crate::model::RelationshipCardinality::One => value,
                crate::model::RelationshipCardinality::OptionalOne => format!("{value} | None"),
                crate::model::RelationshipCardinality::Many => format!("Page[{value}]"),
            };
            writeln!(related_overloads,"    @overload\n    def related(self, record_type: Literal[{}], identifier: str, relationship: Literal[{}], top: int = 50) -> {shape}: ...",quote(&entity.id),quote(&relationship.name)).unwrap();
        }
        for path in entity.read_paths.values() {
            let target = &entities[&path.to];
            writeln!(related_overloads,"    @overload\n    def related(self, record_type: Literal[{}], identifier: str, relationship: Literal[{}], top: int = 50) -> Page[RecordView[{}Projection]]: ...",quote(&entity.id),quote(&path.id),target.api_name).unwrap();
        }
    }
    let mut client = PYTHON_CLIENT.to_owned();
    if entities.len() == 1 {
        let entity = entities.values().next().expect("one record type");
        read_overloads.clear();
        client = client.replace(
            "def read(self, record_type: str, identifier: str) -> RecordView[Any]:",
            &format!("def read(self, record_type: Literal[{}], identifier: str) -> RecordView[{}Projection]:", quote(&entity.id), entity.api_name),
        );
    }
    if related_overloads.matches("    @overload").count() == 1 {
        let signature = related_overloads
            .trim_start_matches("    @overload\n")
            .trim_end()
            .trim_end_matches(" ...")
            .trim_start();
        client = client.replace(
            "def related(self, record_type: str, identifier: str, relationship: str, top: int = 50) -> Any:",
            signature,
        );
        related_overloads.clear();
    }
    py.push_str(
        &client
            .replace("    # READ_OVERLOADS", &read_overloads)
            .replace("    # RELATED_OVERLOADS", &related_overloads),
    );
    for action in actions.public_actions() {
        let name = type_name(&action.api_name);
        writeln!(py, "    def {}(self, inputs: {name}Input, key: str) -> {name}Result:\n        return cast({name}Result, self._invoke({}, inputs, key))\n", python_name(&action.api_name), quote(&action.id)).unwrap();
    }
    insert_bytes(
        artifacts,
        "generated/sdk/project.ts",
        "text/typescript",
        ts.into_bytes(),
    );
    // Keep generated Python files newline-terminated without an empty EOF line.
    while py.ends_with("\n\n") {
        py.pop();
    }
    insert_bytes(
        artifacts,
        "generated/sdk/project.py",
        "text/x-python",
        py.into_bytes(),
    );
    Ok(())
}

fn project_definitions(
    entities: &BTreeMap<String, CompiledEntity>,
    actions: &CompiledActionInventory,
) -> Value {
    let mut relationships = BTreeMap::<String, BTreeMap<String, Value>>::new();
    for entity in entities.values() {
        for relationship in entity.relationships.values() {
            let referenced_entity = if relationship.inverse {
                &entities[&relationship.target_entity_id]
            } else {
                entity
            };
            let field = referenced_entity
                .stored_fields
                .iter()
                .find(|field| field.logical.id == relationship.field_id)
                .expect("normalized relationship field");
            relationships.entry(entity.id.clone()).or_default().insert(relationship.name.clone(),json!({
                "kind":if relationship.inverse {"inverse"} else {"forward"},"target":relationship.target_entity_id,
                "field":field.logical.api_name,"cardinality":relationship.cardinality}));
        }
        for path in entity.read_paths.values() {
            relationships.entry(entity.id.clone()).or_default().insert(
                path.id.clone(),
                json!({"kind":"join","target":path.to,"path":path.id}),
            );
        }
    }
    json!({"records":entities.values().map(|entity| (entity.id.clone(), json!({"route":entity.route,
        "titleField":entity.display.title_field.as_ref().and_then(|id|entity.stored_fields.iter().find(|field|field.logical.id==*id)).map(|field|&field.logical.api_name)}))).collect::<BTreeMap<_,_>>(),
        "actions":actions.public_actions().map(|action|(action.id.clone(),json!({"mode":if action.execution.is_proposal(){"proposal"}else{"immediate"},
            "conditionInputs":if action.execution.is_proposal(){Vec::new()}else{crate::plan::condition_inputs(action).into_iter().filter_map(|id|action.inputs.iter().find(|input|input.id==id).map(|input|input.api_name.clone())).collect::<Vec<_>>()},
            "refusals":action.handler.as_ref().map(|function|function.refusals.keys().collect::<Vec<_>>()).unwrap_or_default()}))).collect::<BTreeMap<_,_>>(),
        "relationships":relationships})
}

fn python_literal(value: &Value) -> String {
    match value {
        Value::Null => "None".to_owned(),
        Value::Bool(true) => "True".to_owned(),
        Value::Bool(false) => "False".to_owned(),
        Value::Array(values) => format!(
            "[{}]",
            values
                .iter()
                .map(python_literal)
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Value::Object(values) => format!(
            "{{{}}}",
            values
                .iter()
                .map(|(key, value)| format!("{}: {}", quote(key), python_literal(value)))
                .collect::<Vec<_>>()
                .join(", ")
        ),
        _ => serde_json::to_string(value).expect("value serializes"),
    }
}
fn python_name(name: &str) -> String {
    name.chars()
        .enumerate()
        .flat_map(|(index, character)| {
            if character.is_uppercase() && index > 0 {
                vec!['_', character.to_ascii_lowercase()]
            } else {
                vec![character.to_ascii_lowercase()]
            }
        })
        .collect()
}

fn quote(value: &str) -> String {
    serde_json::to_string(value).expect("string serializes")
}
fn type_name(value: &str) -> String {
    let mut chars = value.chars();
    chars
        .next()
        .map(|first| first.to_uppercase().collect::<String>() + chars.as_str())
        .unwrap_or_default()
}
fn write_types(ts: &mut String, py: &mut String, name: &str, fields: &[(&str, Value, bool)]) {
    writeln!(ts, "export interface {name} {{").unwrap();
    writeln!(py, "{name} = TypedDict({}, {{", quote(name)).unwrap();
    for (name, schema, required) in fields {
        writeln!(
            ts,
            "  readonly {}{}: {};",
            quote(name),
            if *required { "" } else { "?" },
            schema_type(schema, false)
        )
        .unwrap();
        let value = schema_type(schema, true);
        writeln!(
            py,
            "    {}: {},",
            quote(name),
            if *required {
                value
            } else {
                format!("NotRequired[{value}]")
            }
        )
        .unwrap();
    }
    ts.push_str("}\n\n");
    py.push_str("})\n\n");
}
fn schema_type(schema: &Value, python: bool) -> String {
    if let Some(variants) = schema.get("anyOf").and_then(Value::as_array) {
        return variants
            .iter()
            .map(|variant| schema_type(variant, python))
            .collect::<Vec<_>>()
            .join(" | ");
    }
    if let Some(values) = schema.get("enum").and_then(Value::as_array) {
        let values = values
            .iter()
            .map(|value| serde_json::to_string(value).unwrap())
            .collect::<Vec<_>>();
        return if python {
            format!("Literal[{}]", values.join(", "))
        } else {
            values.join(" | ")
        };
    }
    match schema.get("type").and_then(Value::as_str) {
        Some("null") => {
            if python {
                "None"
            } else {
                "null"
            }
        }
        Some("string") => {
            if python {
                "str"
            } else {
                "string"
            }
        }
        Some("boolean") => {
            if python {
                "bool"
            } else {
                "boolean"
            }
        }
        Some("integer") => {
            if python {
                "int"
            } else {
                "number"
            }
        }
        Some("number") => {
            if python {
                "float"
            } else {
                "number"
            }
        }
        Some("array") => {
            return format!(
                "{}{}{}",
                if python { "list[" } else { "ReadonlyArray<" },
                schema_type(&schema["items"], python),
                if python { "]" } else { ">" }
            );
        }
        _ => {
            if python {
                "dict[str, object]"
            } else {
                "Readonly<Record<string, unknown>>"
            }
        }
    }
    .to_owned()
}

const TYPESCRIPT_CONTRACT: &str = r#"
export type EngineReason = 'pending-review' | 'review-rejected' | 'review-changes-requested' | 'review-ended' | 'stale-revision' | 'package-changed' | 'dependency-outage' | 'invalid-input' | 'already-applied';
export type RecoveryHint = 'refresh' | 'revise' | 'retry' | 'rebase' | 'correct-input' | 'receipt-only';
export type Availability<R extends string = EngineReason> =
  | { readonly available: true; readonly observedRevision: number }
  | { readonly available: false; readonly observedRevision: number; readonly reason: R; readonly recovery: RecoveryHint };
export interface RecordReference<T> { readonly recordType: string; readonly recordId: string; readonly revision: number; readonly data?: T }
export interface RecordView<T> { readonly id: string; readonly revision: string; readonly title: string; readonly data: Partial<T> }
export interface Proposal<I, R extends string = EngineReason> { readonly native: breg.BRegProposal; readonly document: Omit<breg.BRegProposalDocument, 'links' | 'input'> & {readonly input?: Partial<I>; readonly links: Readonly<Partial<Record<breg.BRegProposalTransition | 'self' | 'reviewContext' | 'reviewStatus', Omit<breg.BRegProposalLink, 'availability'> & {readonly availability?: Availability<R>}>>>} }
export interface Page<T> { readonly items: readonly T[]; readonly next?: () => Promise<Page<T>> }
"#;
const TYPESCRIPT_CLIENT: &str = r#"
interface ProjectDefinitions {
  records: Readonly<Record<string, {route: string; titleField: string | null}>>;
  actions: Readonly<Record<string, {mode: 'immediate'|'proposal'; refusals: readonly string[]; conditionInputs: readonly string[]}>>;
  relationships: Readonly<Record<string, Readonly<Record<string, {kind: 'forward'|'inverse'|'join'; target: string; field?: string; path?: string; cardinality?: 'one'|'optional-one'|'many'}>>>>;
}
/** Uses the maintained native client's bounded reads and promoted Action/Proposal handles. */
export class ProjectClient {
  constructor(private readonly native: breg.BaseRegistryClient, private readonly profile: string) {}
  private view<T>(recordType: string, record: {recordIdentifier: string; revisionIdentifier: string; domainData: Readonly<Record<string, unknown>>}): RecordView<T> {
    const titleField = definitions.records[recordType]?.titleField;
    const title = titleField ? record.domainData[titleField] : undefined;
    return {id: record.recordIdentifier, revision: record.revisionIdentifier,
      title: typeof title === 'string' && title.length ? title : record.recordIdentifier,
      data: record.domainData as Partial<T>};
  }
  async read<K extends keyof ProjectRecords>(recordType: K, id: string): Promise<RecordView<ProjectRecords[K]>> {
    const result = await this.native.getRecord(definitions.records[recordType].route, id, {accessProfile: this.profile});
    return this.view(recordType, result.value.data);
  }
  async related<K extends keyof ProjectRelationships, R extends keyof ProjectRelationships[K]>(recordType: K, id: string, relationship: R, top = 50): Promise<ProjectRelationships[K][R]> {
    const relation = definitions.relationships[recordType]?.[String(relationship)];
    if (!relation) throw new TypeError('Relationship is not in the compiled project contract');
    const source = await this.read(recordType as keyof ProjectRecords, id);
    if (relation.kind === 'forward') {
      const target = (source.data as Readonly<Record<string, unknown>>)[relation.field!];
      if (target == null) {
        if (relation.cardinality === 'one') throw new TypeError('Required reference is absent from this readable projection');
        return null as ProjectRelationships[K][R];
      }
      if (typeof target !== 'string') throw new TypeError('Reference is not a record identifier');
      return await this.read(relation.target as keyof ProjectRecords, target) as ProjectRelationships[K][R];
    }
    // UUID validation precedes composing the governed equality filter.
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id)) throw new TypeError('Record identifier is invalid');
    const page = <C>(result: breg.PageOutcome<breg.RecordCollection, C>, resume: (continuation: C) => Promise<breg.PageOutcome<breg.RecordCollection, C>>): Page<RecordView<unknown>> => ({
      items: result.value.items.map(record => this.view(relation.target, record)),
      next: result.continuation ? async () => page(await resume(result.continuation!), resume) : undefined,
    });
    const result = relation.kind === 'join'
      ? page(await this.native.listRelationshipRecords(definitions.records[recordType].route, id, relation.path!, {accessProfile: this.profile, top}), continuation => this.native.continueRelationshipList(continuation))
      : page(await this.native.listRecords(definitions.records[relation.target].route, {accessProfile: this.profile, top, filter: `${relation.field} eq '${id}'`}), continuation => this.native.continueList(continuation));
    if (relation.cardinality === 'one') {
      if (result.items.length !== 1 || result.next) throw new TypeError('Required relationship did not resolve exactly one readable record');
      return result.items[0] as ProjectRelationships[K][R];
    }
    if (relation.cardinality === 'optional-one') {
      if (result.items.length > 1 || result.next) throw new TypeError('Singular relationship resolved multiple records');
      return (result.items[0] ?? null) as ProjectRelationships[K][R];
    }
    return result as ProjectRelationships[K][R];
  }
  async invoke<K extends keyof ProjectActions>(action: K, input: ProjectActions[K]['input'], key: string): Promise<ProjectActions[K]['result']> {
    const metadata = await this.native.registryContract(this.profile);
    const binding = metadata.selectAction(action, this.profile);
    const values = input as unknown as breg.JsonObject;
    if (definitions.actions[action].mode === 'proposal') {
      const native = await this.native.startProposal(binding, values, key);
      return {native, document: JSON.parse(native.documentJson)} as ProjectActions[K]['result'];
    }
    const required = definitions.actions[action].conditionInputs;
    const conditions = required.length ? await this.native.actionTargetConditions(binding,
      Object.fromEntries(required.map(name => [name, values[name]])) as breg.JsonObject) : undefined;
    const outcome = await this.native.invokeAction(binding, values, key, conditions);
    return outcome.value as unknown as ProjectActions[K]['result'];
  }
  async listProposals<K extends keyof ProjectActions>(action: K, cursor?: string): Promise<Page<Proposal<ProjectActions[K]['input']>>> {
    const metadata = await this.native.registryContract(this.profile);
    const collection = metadata.selectProposals(this.profile);
    const query: breg.JsonObject = cursor === undefined ? {action: String(action)} : {action: String(action), cursor};
    const result = await this.native.listProposals(collection, query);
    return {items: result.items.map(native => ({native, document: JSON.parse(native.documentJson)})),
      next: result.nextCursor ? () => this.listProposals(action, result.nextCursor!) : undefined};
  }
  async resumeProposal<I, R extends string>(proposal: Proposal<I, R>): Promise<Proposal<I, R>> {
    const native = await this.native.readProposal(proposal.native);
    return {native, document: JSON.parse(native.documentJson)};
  }
  prepare<I, R extends string>(proposal: Proposal<I, R>, transition: breg.BRegProposalTransition, body: breg.JsonObject, key: string): breg.BRegPreparedProposal {
    return this.native.prepareProposal(proposal.native, transition, body, key);
  }
  async execute<I, R extends string>(attempt: breg.BRegPreparedProposal): Promise<Proposal<I, R>> {
    const native = await this.native.executeProposal(attempt);
    return {native, document: JSON.parse(native.documentJson)};
  }
}
"#;
const PYTHON_CONTRACT: &str = r#"
EngineReason = Literal['pending-review', 'review-rejected', 'review-changes-requested', 'review-ended', 'stale-revision', 'package-changed', 'dependency-outage', 'invalid-input', 'already-applied']
RecoveryHint = Literal['refresh', 'revise', 'retry', 'rebase', 'correct-input', 'receipt-only']
class Availability(TypedDict):
    available: bool
    observedRevision: int
    reason: NotRequired[EngineReason]
    recovery: NotRequired[RecoveryHint]
class RecordReference(TypedDict):
    recordType: str
    recordId: str
    revision: int
I = TypeVar('I')
T = TypeVar('T')
class RecordView(TypedDict, Generic[T]):
    id: str
    revision: str
    title: str
    data: T
class Page(TypedDict, Generic[T]):
    items: list[T]
    next: NotRequired[Callable[[], Page[T]]]
@dataclass(frozen=True)
class Proposal(Generic[I]):
    native: Any
    document: dict[str, Any]
    @property
    def input(self) -> I | None:
        return cast(I | None, self.document.get('input'))

"#;

const PYTHON_CLIENT: &str = r#"
class NativeMetadata(Protocol):
    def select_action(self, action: str, profile: str) -> Any: ...
    def select_proposals(self, profile: str) -> Any: ...
class NativeClient(Protocol):
    def registry_contract(self, access_profile: str) -> NativeMetadata: ...
    def get_record(self, route: str, identifier: str, **options: Any) -> Any: ...
    def list_records(self, route: str, **options: Any) -> Any: ...
    def list_relationship_records(self, route: str, identifier: str, path: str, **options: Any) -> Any: ...
    def continue_list(self, continuation: Any) -> Any: ...
    def continue_relationship_list(self, continuation: Any) -> Any: ...
    def action_target_conditions(self, binding: Any, inputs: Any) -> Any: ...
    def invoke_action(self, binding: Any, inputs: Any, key: str, conditions: Any = None) -> Any: ...
    def start_proposal(self, binding: Any, inputs: Any, key: str) -> Any: ...
    def list_proposals(self, collection: Any, query: Any) -> Any: ...
    def read_proposal(self, proposal: Any) -> Any: ...
    def prepare_proposal(self, proposal: Any, transition: str, body: Any, key: str) -> Any: ...
    def execute_proposal(self, attempt: Any) -> Any: ...

class ProjectClient:
    def __init__(self, native: NativeClient, profile: str):
        self._native, self._profile = native, profile
    def _view(self, record_type: str, record: Any) -> RecordView[Any]:
        field = _definitions['records'][record_type]['titleField']
        title = record['domainData'].get(field) if field else None
        return {'id': record['recordIdentifier'], 'revision': record['revisionIdentifier'],
                'title': title if isinstance(title, str) and title else record['recordIdentifier'], 'data': record['domainData']}
    # READ_OVERLOADS
    def read(self, record_type: str, identifier: str) -> RecordView[Any]:
        return self._read(record_type, identifier)
    def _read(self, record_type: str, identifier: str) -> RecordView[Any]:
        result = self._native.get_record(_definitions['records'][record_type]['route'], identifier, access_profile=self._profile)
        return self._view(record_type, result['value']['data'])
    # RELATED_OVERLOADS
    def related(self, record_type: str, identifier: str, relationship: str, top: int = 50) -> Any:
        relation = _definitions['relationships'][record_type][relationship]
        source = self._read(record_type, identifier)
        if relation['kind'] == 'forward':
            target = source['data'].get(relation['field'])
            if target is None and relation.get('cardinality') == 'one':
                raise ValueError('Required reference is absent from this readable projection')
            return self._read(relation['target'], target) if target else None
        from uuid import UUID
        if str(UUID(identifier)) != identifier:
            raise ValueError('Record identifier is invalid')
        if relation['kind'] == 'join':
            result = self._native.list_relationship_records(_definitions['records'][record_type]['route'], identifier, relation['path'], access_profile=self._profile, top=top)
        else:
            result = self._native.list_records(_definitions['records'][relation['target']]['route'], access_profile=self._profile, top=top, filter=f"{relation['field']} eq '{identifier}'")
        def page(result: Any) -> Page[RecordView[Any]]:
            value: Page[RecordView[Any]] = {'items': [cast(RecordView[Any], self._view(relation['target'], item)) for item in result['value']['items']]}
            continuation = result.get('continuation')
            if continuation:
                resume = self._native.continue_relationship_list if relation['kind'] == 'join' else self._native.continue_list
                value['next'] = lambda: page(resume(continuation))
            return value
        value=page(result)
        if relation.get('cardinality') in ('one','optional-one'):
            if len(value['items']) > 1 or 'next' in value:
                raise ValueError('Singular relationship resolved multiple records')
            if not value['items'] and relation['cardinality'] == 'one':
                raise ValueError('Required relationship did not resolve one readable record')
            return value['items'][0] if value['items'] else None
        return value
    def _invoke(self, action: str, inputs: Any, key: str) -> Any:
        metadata = self._native.registry_contract(self._profile)
        binding = metadata.select_action(action, self._profile)
        if _definitions['actions'][action]['mode'] == 'proposal':
            native = self._native.start_proposal(binding, inputs, key)
            return Proposal(native, native.document)
        required = _definitions['actions'][action]['conditionInputs']
        conditions = self._native.action_target_conditions(binding, {name: inputs[name] for name in required}) if required else None
        return self._native.invoke_action(binding, inputs, key, conditions)['value']
    def list_proposals(self, action: str, cursor: str | None = None) -> dict[str, Any]:
        collection = self._native.registry_contract(self._profile).select_proposals(self._profile)
        result = self._native.list_proposals(collection, {'action': action, 'cursor': cursor})
        return {'items': [Proposal(native, native.document) for native in result.items], 'nextCursor': result.next_cursor}
    def resume_proposal(self, proposal: Proposal[I]) -> Proposal[I]:
        native = self._native.read_proposal(proposal.native)
        return Proposal(native, native.document)
    def prepare(self, proposal: Proposal[I], transition: str, body: dict[str, Any], key: str) -> Any:
        return self._native.prepare_proposal(proposal.native, transition, body, key)
    def execute(self, attempt: Any) -> Proposal[Any]:
        native = self._native.execute_proposal(attempt)
        return Proposal(native, native.document)

"#;

#[cfg(test)]
mod tests {
    use super::{PYTHON_CONTRACT, TYPESCRIPT_CLIENT, TYPESCRIPT_CONTRACT};

    #[test]
    fn typescript_project_client_passes_proposal_objects_to_the_native_client() {
        for call in [
            "startProposal(binding, values, key)",
            "cursor === undefined ? {action: String(action)} : {action: String(action), cursor}",
            "listProposals(collection, query)",
            "prepareProposal(proposal.native, transition, body, key)",
        ] {
            assert!(TYPESCRIPT_CLIENT.contains(call), "missing {call}");
        }
        for retired in [
            "JSON.stringify(input)",
            "JSON.stringify({action, cursor})",
            "JSON.stringify(body)",
        ] {
            assert!(!TYPESCRIPT_CLIENT.contains(retired), "retained {retired}");
        }
    }

    #[test]
    fn recovery_vocabulary_names_rebase_and_omits_terminal() {
        for contract in [TYPESCRIPT_CONTRACT, PYTHON_CONTRACT] {
            assert!(contract.contains("'package-changed'"), "{contract}");
            assert!(!contract.contains("'contract-changed'"), "{contract}");
            assert!(contract.contains("'rebase'"), "{contract}");
            assert!(!contract.contains("'terminal'"), "{contract}");
        }
    }
}
